"""
Configuration for the Static HTML Crypto Table Scraper.

PAGE_SOURCE can be either:
  - A local file path  (e.g. "page.html" or "../data/mock_coinmarketcap.html")
  - A URL starting with "http"  (e.g. "https://example.com/crypto.html")

The scraper detects which type automatically, so you can swap between
local development and a hosted page without changing any other code.
"""

import os

# ─── Source Page ────────────────────────────────────────────────────────────────
# Points to the static HTML page that contains the crypto data table.
# By default, uses the same mock page generated by the Selenium project.
PAGE_SOURCE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)),
    "..",
    "data",
    "mock_coinmarketcap.html",
)

# ─── Output ─────────────────────────────────────────────────────────────────────
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DATA_DIR = os.path.join(BASE_DIR, "data")
CSV_PATH = os.path.join(DATA_DIR, "static_prices.csv")

# ─── Scraping Parameters ────────────────────────────────────────────────────────
TOP_N = 10  # Maximum number of coin rows to extract

# ─── Optional Filters (mirror the Selenium project's settings) ──────────────────
PRICE_THRESHOLD = None        # Minimum USD price, e.g. 100.0 or None
TOP_GAINERS_ONLY = False      # Keep only coins with positive 24h change

# ─── HTTP Settings (used only when PAGE_SOURCE is a URL) ────────────────────────
REQUEST_TIMEOUT = 10  # seconds
USER_AGENT = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
    "AppleWebKit/537.36 (KHTML, like Gecko) "
    "Chrome/122.0.0.0 Safari/537.36"
)
